mapper.insert:
INSERT INTO auth_verifications (
	email, purpose, code_hash, fail_count, created_at
)
VALUES (
	#{email}, #{purpose}, #{codeHash}, 0, #{createdAt}
)

mapper.select:
SELECT MAX(created_at)
FROM auth_verifications
WHERE email = #{email}

SELECT COUNT(*)
FROM auth_verifications
WHERE email = #{email}
  AND created_at > #{since}

SELECT *
FROM auth_verifications
WHERE email = #{email}
  AND purpose = #{purpose}
ORDER BY verification_num DESC
LIMIT 1

mapper.update:
UPDATE auth_verifications
SET fail_count = fail_count + 1
WHERE verification_num = #{verificationNum}

UPDATE auth_verifications
SET used_at = #{usedAt}
WHERE verification_num = #{verificationNum}
  AND used_at IS NULL
